import { Component, Suspense, useEffect, useLayoutEffect, useMemo, useRef, type ReactNode } from 'react';
import { useGLTF } from '@react-three/drei';
import type { Group, Material, Mesh } from 'three';
import {
  applySurfaceDetail,
  NO_DETAIL_FLAG,
  preloadSurfaceDetail,
  useSurfaceDetailMap,
} from './detail';

/**
 * Blender-authored asset loading.
 *
 * The models in `public/models` are generated by `tools/blender/build_assets.py`.
 * If any file is missing or unreadable the boundary below silently falls back to
 * the procedural geometry in `World.tsx`, so an absent asset degrades the look
 * but never blocks play.
 */

const MODEL_BASE = '/models/';

/** Uniform scale applied to Blender-authored assets to match world units. */
const MODEL_SCALE: Record<string, number> = {
  weaver: 1,
  spark: 1,
};

export function modelPath(name: string): string {
  return `${MODEL_BASE}${name}.glb`;
}

/**
 * Catches a failed model load. R3F surfaces a failed fetch as a thrown error
 * from the suspending promise, which React routes to the nearest boundary.
 */
class AssetBoundary extends Component<
  { fallback: ReactNode; children: ReactNode },
  { failed: boolean }
> {
  state = { failed: false };

  static getDerivedStateFromError() {
    return { failed: true };
  }

  componentDidCatch(error: unknown) {
    if (import.meta.env.DEV) {
      console.warn('[ILMEK] falling back to procedural geometry:', error);
    }
  }

  render() {
    return this.state.failed ? this.props.fallback : this.props.children;
  }
}

export interface LoadedModel {
  scene: Group;
  animations: never[];
}

function useModel(name: string): LoadedModel {
  return useGLTF(modelPath(name)) as unknown as LoadedModel;
}

/** Warm the loader so the first frame does not stall. */
export function preloadModels(names: string[]): void {
  for (const name of names) {
    try {
      useGLTF.preload(modelPath(name));
    } catch {
      /* a missing model simply falls back at render time */
    }
  }
}

/**
 * Locomotion states the player character can be in.
 *
 * The adopted CC0 character (KayKit Adventurers, Kay Lousberg — CC0-1.0) ships
 * far more clips than the game uses; `CLIP_FOR_STATE` maps the four states the
 * player can actually be in onto the source clips. Turn uses the two strafe
 * clips, which is what they animate.
 */
export type LocomotionState = 'idle' | 'walk' | 'run' | 'turnLeft' | 'turnRight';

export const CLIP_FOR_STATE: Record<LocomotionState, string> = {
  idle: 'Idle',
  walk: 'Walking_A',
  run: 'Running_A',
  turnLeft: 'Running_Strafe_Left',
  turnRight: 'Running_Strafe_Right',
};

export const LOCOMOTION_STATES: readonly LocomotionState[] = [
  'idle', 'walk', 'run', 'turnLeft', 'turnRight',
];

/**
 * The source model is authored at 3.36 units tall with its feet at y = -1.16.
 * Scaling and lifting it here puts the boots on the ground at world y = 0.
 */
export const CHARACTER_SCALE = 0.6;
export const CHARACTER_Y_OFFSET = 0.7;

export const ALL_MODEL_NAMES = [
  'weaver',
  'synthesis_tree',
  'console',
  'terrace_map',
  'great_loom',
  'council_city',
  'cloud_harbour',
  'collective_gardens',
  'observer_mirrors',
  'living_valley',
];
// `tapestry.glb` is deliberately absent and is no longer rendered. It is a
// single mesh with two materials and no emissive channel, so it cannot express
// the panel-by-panel progression the tapestry exists to show; `World.tsx` builds
// the panels from primitives instead. The file is left on disk because it is a
// build product of `tools/blender/landmarks.py`, not something to hand-delete.
//
// `spark.glb` is absent for the opposite reason: `Spark` in `Scene.tsx` is
// built entirely from primitives and never loaded a model. Listing it here made
// the game download 22 KB of a file nothing reads, and — worse for the next
// reader — putting it in `CREATURE_MODELS` below implied the companion was a
// GLB that had to be kept away from the stone detail pass. It is procedural,
// flat-shaded, and 0.26 units across.

/**
 * Models that are characters rather than architecture — currently just the
 * player. Anything loaded here is kept out of the stone detail pass: the
 * projection is world-space, so on something that moves the grain would swim
 * across it. The baked tone break-up is a vertex attribute and stays locked to
 * the mesh, which is why that one is harmless.
 */
const CREATURE_MODELS = new Set(['weaver']);

/** Warms the stone detail map alongside the models themselves. */
preloadSurfaceDetail();

export interface AssetProps {
  /** File name under `/models`, without the extension. */
  name: string;
  /** Rendered when the model cannot be loaded. */
  fallback: ReactNode;
  position?: [number, number, number];
  rotation?: [number, number, number];
  scale?: number;
  /** Uniform scale applied only to the model, leaving the fallback untouched. */
  visible?: boolean;
  /**
   * Called for every mesh in the model, on load and again whenever `paintKey`
   * changes. The escape hatch for state that has to live on the geometry
   * itself: a GLB is one static file, so anything the game wants to change —
   * a branch that lights when a connection is made — can only be expressed by
   * reaching into the loaded scene rather than by swapping the model out.
   */
  paint?: (mesh: Mesh) => void;
  /** Change this to re-apply `paint`. */
  paintKey?: unknown;
}

/**
 * Renders a Blender asset when it is available, otherwise the supplied
 * procedural fallback. `position` and `rotation` are applied either way so the
 * two representations occupy exactly the same place in the world.
 */
export function Asset({
  name,
  fallback,
  position,
  rotation,
  scale,
  visible,
  paint,
  paintKey,
}: AssetProps) {
  return (
    <AssetBoundary fallback={fallback}>
      <Suspense fallback={fallback}>
        <AssetMesh
          name={name}
          position={position}
          rotation={rotation}
          scale={scale}
          visible={visible}
          paint={paint}
          paintKey={paintKey}
        />
      </Suspense>
    </AssetBoundary>
  );
}

function AssetMesh({
  name,
  position,
  rotation,
  scale,
  visible,
  paint,
  paintKey,
}: Omit<AssetProps, 'fallback'>) {
  const { scene } = useModel(name);
  const resolved = useMemo(() => scale ?? MODEL_SCALE[name] ?? 1, [scale, name]);
  const detailMap = useSurfaceDetailMap();

  /**
   * Each `<Asset>` renders its own copy of the loaded scene.
   *
   * `useModel` is a cache: every call with the same name hands back the *same*
   * Object3D. Rendering that object from more than one `<primitive>` asks
   * three.js to give one node twenty-eight parents, and the last one to mount
   * wins — so the twenty-eight puzzle consoles in this world were all drawing
   * their authored plinth at a single spot near the spawn, and not one console
   * had a plinth where the player actually stands. The landmarks were fine
   * only because each of them is a different file.
   *
   * A deep clone gives every instance its own transform tree. Geometry and
   * materials stay shared, which is what makes this cheap: the console is 657
   * vertices across four meshes, and `applySurfaceDetail` is guarded by
   * `PATCH_FLAG`, so the shared materials are still patched exactly once.
   */
  const instance = useMemo(() => (scene ? scene.clone(true) : null), [scene]);

  // Synced in a layout effect rather than assigned during render: an inline
  // arrow would otherwise give `paint` a new identity on every render and drag
  // the effect below along with it. Layout effects run in declaration order, so
  // this one is always current by the time the painter runs.
  const paintRef = useRef(paint);
  useLayoutEffect(() => {
    paintRef.current = paint;
  }, [paint]);

  // A layout effect, not `useMemo`: patching a material is a side effect, and
  // this has to land before the browser paints so the landmark is never shown
  // untextured while three.js recompiles the program.
  useLayoutEffect(() => {
    if (!instance) return;
    if (CREATURE_MODELS.has(name)) {
      // Opt these out by name rather than skipping them here: the scene-wide
      // pass in `Scene.tsx` walks every material in the world, and it has no
      // way to know which mesh belongs to a creature.
      instance.traverse((child: unknown) => {
        const mesh = child as Mesh & { material?: { userData?: Record<string, unknown> } };
        const material = mesh.material;
        if (material?.userData) material.userData[NO_DETAIL_FLAG] = true;
      });
      return;
    }
    applySurfaceDetail(instance, detailMap);
  }, [instance, detailMap, name]);

  // Per-model state painted onto the loaded geometry, the way `StageConsole`
  // keeps its state-driven mark in code while the plinth stays a model.
  useLayoutEffect(() => {
    if (!instance || !paintRef.current) return;
    instance.traverse((child: unknown) => {
      const mesh = child as Mesh;
      if (mesh.isMesh) paintRef.current?.(mesh);
    });
  }, [instance, paintKey]);

  useEffect(() => {
    // Trailing colour-space correction so PBR materials match the procedural
    // meshes rendered elsewhere in the scene.
    instance?.traverse((child: unknown) => {
      const mesh = child as Mesh;
      // A loaded GLB carries no shadow flags: the glTF format has no concept
      // of them, so every landmark was floating until it was told to cast and
      // receive like the procedural geometry around it.
      if (mesh.isMesh) {
        mesh.castShadow = true;
        mesh.receiveShadow = true;
      }
      const material = mesh.material as Material | undefined;
      if (!material) return;
      // Raised from 0.7 now that a real environment probe exists. The original
      // value was chosen against a scene with no reflections at all, where a
      // higher one only washed the metal out.
      if ('envMapIntensity' in material) {
        material.envMapIntensity = 1;
      }
      // Vertex AO, baked in Blender, arrives in COLOR_0. The material has to be
      // told to read it — glTF does not switch this on by itself, so without
      // this the bake loads and is never seen.
      if ('vertexColors' in material && mesh.geometry?.getAttribute('color')) {
        (material as { vertexColors: boolean }).vertexColors = true;
      }
    });
  }, [instance]);

  if (!instance || visible === false) return null;
  return (
    <primitive
      object={instance}
      position={position}
      rotation={rotation}
      scale={resolved}
    />
  );
}